import utils from '@/common/utils.js';
export default {
	props: {
		orderData: {
			required: true,
			type: Object,
			// 如果这里结构报错，就把default定义为函数，内部return默认值即可
			default() {
				return {};
			}
		}
	},
	data() {
		return {};
	},
	onLoad() {},
	methods: {},
	computed: {
		formatTime() {
			const time = this.orderData.payTime;
			if(!time) return
			return utils.formatDate(time, 'yyyy-MM-dd hh:mm:ss');
		}
	}
};
